// Demonstrating structure padding and alignment requirements

struct S {
    char a;      // 1 byte
    int b;       // 4 bytes
    short c;     // 2 bytes
};
// On systems where int alignment is 4, sizeof(S) is often 12:
// 1(a) + 3(pad) + 4(b) + 2(c) + 2(pad)

size_t struct_size = sizeof(S);
size_t struct_align = alignof(S);

// Enforcing specific alignment
struct alignas(64) CacheLineData {
    long long data[7];
};

// Alignment checking
constexpr bool is_aligned_64 = (alignof(CacheLineData) == 64);

// C++ standard maximum alignment requirement
using MaxAlign = std::max_align_t;
size_t max_req = alignof(MaxAlign);
